import os, re, json

def load():
    d = os.environ['RLM_SESSION_DIR']
    path = os.path.join(d, '../../sessions', os.path.basename(d) + '.jsonl')
    content = open(path).read().replace('\\n', '\n')

    G = {}
    lines = content.split('\n')
    i = 0

    while i < len(lines):
        line = lines[i].strip()
        if 'Demo pair' in line or ('Test input' in line and line.startswith('Test')):
            match = re.match(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\s*(\d+)', line)
            if match:
                k, h, w, val = match.groups()
                k = k.strip()
                rows = []
                i += 1
                # Parse grid rows from next lines until we have h rows with w columns each
                parsed = False
                while i < len(lines) and not parsed:
                    row_line = lines[i].strip()
                    if row_line:
                        parts = row_line.split()
                        if len(parts) == w:
                            rows.append([int(x) for x in parts])
                            if len(rows) == h:
                                parsed = True
                    i += 1

                if k not in G and rows:
                    G[k] = rows

        elif line == '' and G:
            break
        i += 1

    return G

G = load()
print("Loaded grids:", sorted(G.keys()))
for k in sorted(G.keys()):
    print(f"\n{k}: {len(G[k])}x{len(G[k][0])}")

